<script setup lang="ts">import{projects}from'@/data/projects';import RevealOnScroll from './RevealOnScroll.vue';import SectionHeading from './SectionHeading.vue'</script><template><section id="work" class="section"><SectionHeading eyebrow="Selected concepts / 2024—26" title="Built to make the design feel inevitable."/><p class="work-note">Independent concept work, created to show my frontend and interaction approach.</p><div class="projects"><RevealOnScroll v-for="(project,index) in projects" :key="project.slug"><RouterLink class="project" :to="`/work/${project.slug}`"><div class="image"><img :src="project.image" :alt="`${project.name} concept project preview`" width="1600" height="1000" loading="lazy"><span>Explore concept ↗</span></div><div class="meta"><p>0{{index+1}} / {{project.type}}</p><h3>{{project.name}}</h3><p class="project-status">{{project.status}}</p><p>{{project.description}}</p></div></RouterLink></RevealOnScroll></div></section></template><style scoped>.work-note{max-width:36rem;margin:-3rem 0 5rem;color:var(--muted);font-size:.88rem;line-height:1.55}.projects{display:grid;gap:8rem}.project{color:inherit;text-decoration:none;display:grid;grid-template-columns:2fr 1fr;gap:3rem}.image{position:relative;overflow:hidden;background:#ddd;aspect-ratio:16/10}.image img{width:100%;height:100%;object-fit:cover;transition:transform .7s var(--ease),filter .5s}.image span{position:absolute;right:1rem;bottom:1rem;padding:.9rem 1rem;background:var(--acid);color:#111;font:600 .72rem var(--sans);transform:translateY(130%);transition:transform .4s var(--ease)}.project:hover img{transform:scale(1.025);filter:saturate(.8)}.project:hover .image span{transform:none}.meta{align-self:end;border-top:1px solid;padding-top:1rem}.meta>p:first-child,.project-status{font:600 .65rem var(--sans);text-transform:uppercase;letter-spacing:.1em;color:var(--muted)}.project-status{margin:0 0 1rem;color:#222}h3{font:500 clamp(3rem,5vw,5.5rem)/.9 var(--display);letter-spacing:-.04em;margin:2rem 0}.meta>p:last-child{color:var(--muted);max-width:30rem}@media(max-width:800px){.work-note{margin:-1.5rem 0 3rem}.projects{gap:5rem}.project{grid-template-columns:1fr;gap:1.5rem}.meta h3{margin:1.5rem 0}.image span{transform:none}}</style>
